<?php
$config=require __DIR__.'/saki-config.php';$pdo=new PDO("mysql:host={$config['db_host']};dbname={$config['db_name']};charset=utf8mb4",$config['db_user'],$config['db_password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$rows=[['frame','إطار أزرق','frame_blue',500],['frame','إطار ذهبي','frame_gold',1500],['frame','إطار وردي','frame_pink',1000],['entrance','دخول ناري','entrance_fire',2500]];$q=$pdo->prepare('INSERT INTO saki_store_products(id,category,name,price,media_type,media_url,thumbnail_url,is_active,created_at,duration_days) VALUES(:id,:c,:n,:p,\'asset\',:u,:u,1,UTC_TIMESTAMP(),30)');foreach($rows as $r){$q->execute([':id'=>bin2hex(random_bytes(16)),':c'=>$r[0],':n'=>$r[1],':p'=>$r[3],':u'=>$r[2]]);}echo json_encode(['ok'=>true,'count'=>count($rows)]);
